  els.forEach((e,i)=>{ if(i>0){ e.dot.style.opacity=0; e.tr.style.strokeDasharray=e.len; e.tr.style.strokeDashoffset=e.len; e.tr.setAttribute('opacity','.6'); } e.ring.setAttribute('opacity',0); });
