    const e=els[i], idx=i; const T=420;
    e.tr.animate([{strokeDashoffset:e.len},{strokeDashoffset:0}],{duration:T,easing:'cubic-bezier(.77,0,.18,1)',fill:'forwards'});
    const t0=performance.now(); (function fly(now){ if(id!==run) return; const u=Math.min(1,(now-t0)/T); const k=u<.5?4*u*u*u:1-Math.pow(-2*u+2,3)/2; const pt=e.tr.getPointAtLength(e.len*k); comet.setAttribute('cx',pt.x); comet.setAttribute('cy',pt.y); comet.setAttribute('opacity',u<1?1:0); if(u<1) requestAnimationFrame(fly); else land(e,idx); })(t0);
