function setMeta(v){ const m=META[v]||META.start; document.title=m[0]; let d=document.querySelector('meta[name=description]'); if(d) d.setAttribute('content',m[1]); let c=document.querySelector('link[rel=canonical]'); if(c) c.setAttribute('href','https://the-court.com/'+(v==='start'?'':'#'+v)); }
function route(){ let h=decodeURIComponent(location.hash.slice(1)); let refId=null, postSlug=null; if(h.startsWith('referenzen/')){ refId=h.slice(11); h='referenzen'; } if(h.startsWith('blog/')){ postSlug=h.slice(5); h='blog'; } let v=VIEWS.includes(h)?h:null, t=null;
  if(!v && h){ t=document.getElementById(h); const pv=t&&t.closest('.view'); v=pv?pv.dataset.view:'start'; }
  if(!v) v='start';
  if(window.STATIC_VIEW) v=window.STATIC_VIEW;
  const changed=document.querySelector('.view:not([hidden])')?.dataset.view!==v;
  document.querySelectorAll('.view').forEach(el=>el.hidden=el.dataset.view!==v);
  document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('on',a.dataset.nav===v));
  document.querySelectorAll('[data-nav-group]').forEach(b=>b.classList.toggle('on',b.dataset.navGroup.split(' ').includes(v)));
  closeMenus(); if(!window.STATIC_VIEW) setMeta(v);
  if(window.closeRef) window.closeRef(); if(window.closePost&&!postSlug&&!window.BLOG_OPEN) window.closePost(); if(postSlug&&window.openPost){ window.openPost(postSlug); return; } if(refId&&window.openRef){ if(changed) window.scrollTo(0,0); window.openRef(refId); return; }
  if(!t) window.scrollTo(0,0); else requestAnimationFrame(()=>t.scrollIntoView({behavior:changed?'instant':'smooth'})); }
